public class AppendSeriesSkill
{
    public static void Execute(string chart_id, List<string> x_values, List<string> y_values, int serieIndex)
    {
        Debug.Log("Executing AppendSeriesSkill logic...");

        if (string.IsNullOrEmpty(chart_id))
        {
            Debug.LogWarning("AppendSeriesSkill: chart_id is null or empty.");
            return;
        }

        if (x_values == null || x_values.Count == 0)
        {
            Debug.LogWarning("AppendSeriesSkill: x_values list is null or empty.");
            return;
        }

        if (y_values == null || y_values.Count == 0)
        {
            Debug.LogWarning("AppendSeriesSkill: y_values list is null or empty.");
            return;
        }

        if (x_values.Count != y_values.Count)
        {
            Debug.LogWarning("AppendSeriesSkill: x_values count (" + x_values.Count + ") does not match y_values count (" + y_values.Count + ").");
            return;
        }

        GameObject chartObject = GameObject.Find(chart_id);
        if (chartObject == null)
        {
            Debug.LogWarning("AppendSeriesSkill: GameObject '" + chart_id + "' not found in the scene.");
            return;
        }

        BaseChart chart = chartObject.GetComponent<BaseChart>();
        if (chart == null)
        {
            Debug.LogWarning("AppendSeriesSkill: GameObject '" + chart_id + "' does not have a BaseChart component.");
            return;
        }

        var serie = chart.GetSerie(serieIndex);

        if (serie == null)
        {
            int currentSerieCount = chart.series.Count;
            int seriesToCreate = serieIndex - currentSerieCount + 1;
            for (int s = 0; s < seriesToCreate; s++)
            {
                string serieName = "serie" + (currentSerieCount + s);
                chart.AddSerie<Line>(serieName);
            }
            serie = chart.GetSerie(serieIndex);
            if (serie == null)
            {
                Debug.LogWarning("AppendSeriesSkill: Failed to create serie at index " + serieIndex + ".");
                return;
            }
            Debug.Log("AppendSeriesSkill: Created new Line serie at index " + serieIndex + ".");
        }

        var xAxis = chart.GetChartComponent<XAxis>();
        bool isCategoryAxis = (xAxis != null && xAxis.IsCategory());

        int appendedCount = 0;

        for (int i = 0; i < x_values.Count; i++)
        {
            string xVal = x_values[i];
            string yVal = y_values[i];

            double parsedYValue;
            if (!double.TryParse(yVal, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out parsedYValue))
            {
                Debug.LogWarning("AppendSeriesSkill: Could not parse y_values[" + i + "] '" + yVal + "' as a number. Skipping.");
                continue;
            }

            if (isCategoryAxis)
            {
                bool categoryExists = false;
                if (xAxis.data != null)
                {
                    for (int c = 0; c < xAxis.data.Count; c++)
                    {
                        if (xAxis.data[c] == xVal)
                        {
                            categoryExists = true;
                            break;
                        }
                    }
                }
                if (!categoryExists)
                {
                    chart.AddXAxisData(xVal);
                }
                chart.AddData(serieIndex, parsedYValue, xVal);
            }
            else
            {
                double parsedXValue;
                if (double.TryParse(xVal, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out parsedXValue))
                {
                    chart.AddData(serieIndex, parsedXValue, parsedYValue, xVal);
                }
                else
                {
                    Debug.LogWarning("AppendSeriesSkill: x_values[" + i + "] '" + xVal + "' is not numeric on value axis. Adding y only.");
                    chart.AddData(serieIndex, parsedYValue, xVal);
                }
            }

            appendedCount++;
        }

        Debug.Log("AppendSeriesSkill: Appended " + appendedCount + " of " + x_values.Count + " elements to serie " + serieIndex + " on chart '" + chart_id + "'.");
        chart.RefreshChart();
    }
}

