public class HighlightSkill
{
    public static void Execute(string chart_id, string element_id, string highlight_type)
    {
        Debug.Log("Executing HighlightSkill logic...");

        // Validate inputs
        if (string.IsNullOrEmpty(chart_id))
        {
            Debug.LogWarning("HighlightSkill: chart_id is null or empty.");
            return;
        }

        if (string.IsNullOrEmpty(element_id))
        {
            Debug.LogWarning("HighlightSkill: element_id is null or empty.");
            return;
        }

        if (string.IsNullOrEmpty(highlight_type))
        {
            Debug.LogWarning("HighlightSkill: highlight_type is null or empty.");
            return;
        }

        // Find the GameObject by chart_id and get the BaseChart component
        GameObject chartObject = GameObject.Find(chart_id);
        if (chartObject == null)
        {
            Debug.LogWarning($"HighlightSkill: GameObject '{chart_id}' not found in the scene.");
            return;
        }

        BaseChart chart = chartObject.GetComponent<BaseChart>();
        if (chart == null)
        {
            Debug.LogWarning($"HighlightSkill: GameObject '{chart_id}' does not have a BaseChart component.");
            return;
        }

        // Parse element_id (supports "serieIndex:dataIndex" or plain "dataIndex")
        int serieIndex = 0;
        int dataIndex = 0;

        if (element_id.Contains(":"))
        {
            string[] parts = element_id.Split(':');
            if (!int.TryParse(parts[0], out serieIndex))
            {
                Debug.LogWarning($"HighlightSkill: Could not parse serie index from element_id '{element_id}'.");
                return;
            }
            if (!int.TryParse(parts[1], out dataIndex))
            {
                Debug.LogWarning($"HighlightSkill: Could not parse data index from element_id '{element_id}'.");
                return;
            }
        }
        else
        {
            if (!int.TryParse(element_id, out dataIndex))
            {
                Debug.LogWarning($"HighlightSkill: Could not parse element_id '{element_id}' as an integer index.");
                return;
            }
        }

        // Validate serie exists
        var serie = chart.GetSerie(serieIndex);
        if (serie == null)
        {
            Debug.LogWarning($"HighlightSkill: Serie {serieIndex} not found on chart '{chart_id}'.");
            return;
        }

        // Validate data index is within bounds
        if (dataIndex < 0 || dataIndex >= serie.dataCount)
        {
            Debug.LogWarning($"HighlightSkill: DataIndex {dataIndex} out of range for serie {serieIndex} (count={serie.dataCount}) on chart '{chart_id}'.");
            return;
        }

        switch (highlight_type.ToLower())
        {
            case "select":
                var sdSelect = serie.GetSerieData(dataIndex);
                if (sdSelect != null)
                {
                    sdSelect.selected = true;
                }
                else
                {
                    Debug.LogWarning($"HighlightSkill: SerieData at index {dataIndex} is null.");
                }
                break;

            case "emphasis":
                if (serie.emphasisStyle != null)
                {
                    serie.emphasisStyle.focus = EmphasisStyle.FocusType.Self;
                }
                else
                {
                    Debug.LogWarning("HighlightSkill: serie.emphasisStyle is null. Falling back to selection-only highlight.");
                }
                var sdEmphasis = serie.GetSerieData(dataIndex);
                if (sdEmphasis != null)
                {
                    sdEmphasis.selected = true;
                }
                else
                {
                    Debug.LogWarning($"HighlightSkill: SerieData at index {dataIndex} is null.");
                }
                break;

            case "blur":
                if (serie.emphasisStyle != null)
                {
                    serie.emphasisStyle.blurScope = EmphasisStyle.BlurScope.Global;
                }
                else
                {
                    Debug.LogWarning("HighlightSkill: serie.emphasisStyle is null. Falling back to selection-only highlight.");
                }
                var sdBlur = serie.GetSerieData(dataIndex);
                if (sdBlur != null)
                {
                    sdBlur.selected = true;
                }
                else
                {
                    Debug.LogWarning($"HighlightSkill: SerieData at index {dataIndex} is null.");
                }
                break;

            case "none":
                var sdNone = serie.GetSerieData(dataIndex);
                if (sdNone != null)
                {
                    sdNone.selected = false;
                }
                else
                {
                    Debug.LogWarning($"HighlightSkill: SerieData at index {dataIndex} is null.");
                }
                break;

            default:
                Debug.LogWarning($"HighlightSkill: Unknown highlight_type '{highlight_type}'. Supported types: select, emphasis, blur, none.");
                break;
        }

        chart.RefreshChart();
    }
}

using UnityEngine;
using UnityEngine.UI;
using XCharts.Runtime;
using SimpleJSON;
using System.IO;
using System.Collections.Generic;

public class CreateSkill
{
    public static void Execute(string view_id, string data_path, string chart_type, string x_field, string y_field)
    {
        Debug.Log("Executing CreateSkill logic...");

        string fullPath = Path.Combine(Application.dataPath, "Resources", "DataFiles", data_path);
        if (!File.Exists(fullPath))
        {
            Debug.LogWarning("Data file not found: " + fullPath);
            return;
        }

        string jsonContent = File.ReadAllText(fullPath);
        JSONArray dataArray = JSON.Parse(jsonContent).AsArray;
        if (dataArray == null || dataArray.Count == 0)
        {
            Debug.LogWarning("Data is empty or invalid JSON array.");
            return;
        }

        GameObject canvasObj = new GameObject(view_id);
        Canvas canvas = canvasObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        canvasObj.AddComponent<CanvasScaler>();
        canvasObj.AddComponent<GraphicRaycaster>();

        RectTransform canvasRect = canvasObj.GetComponent<RectTransform>();
        canvasRect.sizeDelta = new Vector2(800, 600);
        canvasRect.localScale = new Vector3(0.001f, 0.001f, 0.001f);
        canvasRect.localPosition = Vector3.zero;

        GameObject chartObj = new GameObject(view_id + "_Chart");
        chartObj.transform.SetParent(canvasObj.transform, false);

        RectTransform chartRect = chartObj.AddComponent<RectTransform>();
        chartRect.anchorMin = Vector2.zero;
        chartRect.anchorMax = Vector2.one;
        chartRect.offsetMin = Vector2.zero;
        chartRect.offsetMax = Vector2.zero;

        BaseChart chart = null;
        string ct = chart_type.ToLower().Trim();

        if (ct == "line")
        {
            chart = chartObj.AddComponent<LineChart>();
        }
        else if (ct == "bar")
        {
            chart = chartObj.AddComponent<BarChart>();
        }
        else if (ct == "pie")
        {
            chart = chartObj.AddComponent<PieChart>();
        }
        else if (ct == "scatter")
        {
            chart = chartObj.AddComponent<ScatterChart>();
        }
        else if (ct == "heatmap")
        {
            chart = chartObj.AddComponent<HeatmapChart>();
        }
        else if (ct == "radar")
        {
            chart = chartObj.AddComponent<RadarChart>();
        }
        else if (ct == "ring")
        {
            chart = chartObj.AddComponent<RingChart>();
        }
        else
        {
            Debug.LogWarning("Unknown chart_type: " + chart_type + ". Defaulting to BarChart.");
            chart = chartObj.AddComponent<BarChart>();
        }

        if (chart == null)
        {
            Debug.LogWarning("Failed to create chart component.");
            return;
        }

        chart.SetSize(800, 600);
        chart.ClearData();

        bool isPie = (ct == "pie" || ct == "ring");
        bool isRadar = (ct == "radar");

        if (!isPie && !isRadar)
        {
            Title title = chart.EnsureChartComponent<Title>();
            title.show = true;
            title.text = view_id;

            XAxis xAxis = chart.EnsureChartComponent<XAxis>();
            xAxis.show = true;
            xAxis.type = Axis.AxisType.Category;
            xAxis.splitNumber = 0;
            xAxis.boundaryGap = true;
            xAxis.data.Clear();

            YAxis yAxis = chart.EnsureChartComponent<YAxis>();
            yAxis.show = true;
            yAxis.type = Axis.AxisType.Value;

            Tooltip tooltip = chart.EnsureChartComponent<Tooltip>();
            tooltip.show = true;

            Legend legend = chart.EnsureChartComponent<Legend>();
            legend.show = true;

            chart.EnsureChartComponent<GridCoord>();

            chart.AddSerie<Bar>(y_field);
            if (ct == "line")
            {
                chart.RemoveAllSerie();
                chart.AddSerie<Line>(y_field);
            }
            else if (ct == "scatter")
            {
                chart.RemoveAllSerie();
                chart.AddSerie<Scatter>(y_field);
            }
            else if (ct == "heatmap")
            {
                chart.RemoveAllSerie();
                chart.AddSerie<Heatmap>(y_field);
            }

            for (int i = 0; i < dataArray.Count; i++)
            {
                JSONNode item = dataArray[i];
                string xVal = item[x_field].Value;
                double yVal = item[y_field].AsDouble;

                chart.AddXAxisData(xVal);
                chart.AddData(0, yVal, xVal);
            }
        }
        else if (isPie)
        {
            Title title = chart.EnsureChartComponent<Title>();
            title.show = true;
            title.text = view_id;

            Tooltip tooltip = chart.EnsureChartComponent<Tooltip>();
            tooltip.show = true;

            Legend legend = chart.EnsureChartComponent<Legend>();
            legend.show = true;

            chart.AddSerie<Pie>(y_field);

            for (int i = 0; i < dataArray.Count; i++)
            {
                JSONNode item = dataArray[i];
                string xVal = item[x_field].Value;
                double yVal = item[y_field].AsDouble;

                chart.AddData(0, yVal, xVal);
            }
        }
        else if (isRadar)
        {
            Title title = chart.EnsureChartComponent<Title>();
            title.show = true;
            title.text = view_id;

            Tooltip tooltip = chart.EnsureChartComponent<Tooltip>();
            tooltip.show = true;

            Legend legend = chart.EnsureChartComponent<Legend>();
            legend.show = true;

            RadarCoord radarCoord = chart.EnsureChartComponent<RadarCoord>();
            radarCoord.shape = RadarCoord.Shape.Polygon;

            for (int i = 0; i < dataArray.Count; i++)
            {
                JSONNode item = dataArray[i];
                string xVal = item[x_field].Value;
                double yVal = item[y_field].AsDouble;
                radarCoord.AddIndicator(xVal, 0, yVal * 1.5);
            }

            chart.AddSerie<Radar>(y_field);
            List<double> radarValues = new List<double>();
            for (int i = 0; i < dataArray.Count; i++)
            {
                radarValues.Add(dataArray[i][y_field].AsDouble);
            }
            chart.AddData(0, radarValues, y_field);
        }

        chart.RefreshChart();

        Debug.Log("CreateSkill completed. Chart '" + view_id + "' created with type '" + chart_type + "', " + dataArray.Count + " data points.");
    }
}
